SELECT CASE WHEN rating >= 3.9 THEN 'high' WHEN rating >= 2.5 THEN 'mid' ELSE 'low' END AS rating_bucket, country, MAX(rating) AS max_rating, SORT_ARRAY(COLLECT_SET(country)) AS country_list FROM suppliers WHERE country IN ('DE', 'TH') AND (city IN ('Bangkok', 'Berlin') OR country IN ('DE', 'UK', 'JP')) GROUP BY CASE WHEN rating >= 3.9 THEN 'high' WHEN rating >= 2.5 THEN 'mid' ELSE 'low' END, country HAVING MAX(rating) > 1.8;
